// The first interaction is a conversation; recipe selection is a separate step.
let boranView='welcome';
const serviceBeforeBoran=openService;openService=function(id){if(id==='smith')boranView='welcome';serviceBeforeBoran(id)};
function chooseBoranAction(mode){if(!smithPresent())return false;if(mode==='leave'){$('service').close();keys={};return true}if(!['craft','upgrade','welcome'].includes(mode))return false;boranView=mode;if(mode!=='welcome'){smithMode=mode;smithCategory='sword';smithSelected=null;smithCatalogScroll=0}renderService();$('service').scrollTop=0;return true}
